-- Final public schema of the former Supabase project (18 tables, RLS policies, triggers),
-- generated by applying supabase/migrations/*.sql in order to a clean Postgres 16 and dumping
-- the result (pg_dump --schema-only --schema=public). pg_cron / pg_net calls are replaced by
-- the API's in-process scheduler (see 0003_cron.sql and api/src/scheduler.ts).
SET check_function_bodies = false;
CREATE TYPE public.token_category AS ENUM (
    'core',
    'yield',
    'satellite'
);

CREATE TYPE public.tx_side AS ENUM (
    'buy',
    'sell'
);

CREATE FUNCTION public.get_cron_jobs_status() RETURNS TABLE(jobid bigint, jobname text, schedule text, active boolean, last_run_started timestamp with time zone, last_run_status text, last_run_message text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'cron'
    AS $$
  SELECT
    j.jobid,
    j.jobname,
    j.schedule,
    j.active,
    r.start_time AS last_run_started,
    r.status AS last_run_status,
    r.return_message AS last_run_message
  FROM cron.job j
  LEFT JOIN LATERAL (
    SELECT start_time, status, return_message
    FROM cron.job_run_details d
    WHERE d.jobid = j.jobid
    ORDER BY start_time DESC
    LIMIT 1
  ) r ON true
  ORDER BY j.jobid;
$$;

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

CREATE TABLE public.app_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    btc_address text,
    eth_address text,
    eth_arb_address text,
    sol_address text,
    sol_arb_address text,
    wsteth_contract text DEFAULT '0x5979D7b546E38E414F7E9822514be443A4800529'::text NOT NULL,
    jitosol_contract text DEFAULT '0x83e1d2310Ade410676B1733d16e89f91822FD5c3'::text NOT NULL,
    dca_frequency text DEFAULT 'weekly'::text NOT NULL,
    dca_day text DEFAULT 'Monday'::text NOT NULL,
    default_amount numeric DEFAULT 0 NOT NULL,
    total_capital numeric DEFAULT 0 NOT NULL,
    dca_horizon_weeks integer DEFAULT 52 NOT NULL,
    rebalance_threshold numeric DEFAULT 5 NOT NULL,
    theme text DEFAULT 'dark'::text NOT NULL,
    staking_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    score_base_allocations jsonb DEFAULT '{"0-20": 75, "20-40": 65, "40-60": 55, "60-80": 40, "80-100": 25}'::jsonb NOT NULL,
    regime_multipliers jsonb DEFAULT '{"BEAR": 1.15, "BULL": 1.00, "PANIC": 1.30, "EUPHORIA": 0.60, "SIDEWAYS": 0.85}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    manual_holdings jsonb DEFAULT '{"btc": 0, "eth": 0, "sol": 0}'::jsonb NOT NULL,
    holdings_strategy jsonb DEFAULT '{"BTC": {"hold": 100, "lending": 0, "staking": 0, "trading": 0}, "ETH": {"hold": 50, "lending": 10, "staking": 40, "trading": 0}, "SOL": {"hold": 30, "lending": 20, "staking": 50, "trading": 0}}'::jsonb NOT NULL,
    yield_apys jsonb DEFAULT '{"BTC": {"lending": 2, "staking": 0, "trading": 0}, "ETH": {"lending": 1.8, "staking": 3.2, "trading": 0}, "SOL": {"lending": 4.2, "staking": 7.5, "trading": 0}}'::jsonb NOT NULL,
    arb_addresses jsonb DEFAULT '[]'::jsonb NOT NULL,
    initial_cost_basis jsonb DEFAULT '{"btc": 0, "eth": 0, "sol": 0}'::jsonb NOT NULL,
    dynamic_execution_enabled boolean DEFAULT true NOT NULL,
    user_id uuid
);

CREATE TABLE public.capital_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    amount numeric NOT NULL,
    type text DEFAULT 'MONTHLY'::text NOT NULL,
    note text,
    user_id uuid NOT NULL
);

CREATE TABLE public.dca_executions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    week_number integer NOT NULL,
    coin text NOT NULL,
    kind text NOT NULL,
    amount_usd numeric NOT NULL,
    target_price numeric NOT NULL,
    executed_price numeric,
    quantity numeric DEFAULT 0 NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    filled_at timestamp with time zone,
    notes text,
    user_id uuid NOT NULL,
    CONSTRAINT dca_executions_kind_check CHECK ((kind = ANY (ARRAY['market'::text, 'limit'::text]))),
    CONSTRAINT dca_executions_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'EXECUTED'::text, 'FILLED'::text, 'CANCELLED'::text])))
);

CREATE TABLE public.dca_purchases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    week_number integer NOT NULL,
    total_amount numeric DEFAULT 0 NOT NULL,
    btc_amount numeric DEFAULT 0 NOT NULL,
    eth_amount numeric DEFAULT 0 NOT NULL,
    sol_amount numeric DEFAULT 0 NOT NULL,
    btc_price numeric DEFAULT 0 NOT NULL,
    eth_price numeric DEFAULT 0 NOT NULL,
    sol_price numeric DEFAULT 0 NOT NULL,
    market_amount numeric DEFAULT 0 NOT NULL,
    limit_amount numeric DEFAULT 0 NOT NULL,
    score integer,
    regime text,
    allocation_pct numeric,
    notes text,
    user_id uuid NOT NULL
);

CREATE TABLE public.defi_positions (
    user_id uuid NOT NULL,
    eth_debt double precision DEFAULT 0 NOT NULL,
    usdc_debt double precision DEFAULT 0 NOT NULL,
    confirmed_steps jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.engine_params (
    id integer DEFAULT 1 NOT NULL,
    base_market_high numeric DEFAULT 85 NOT NULL,
    base_market_low numeric DEFAULT 30 NOT NULL,
    base_distance_low numeric DEFAULT '-1.5'::numeric NOT NULL,
    base_distance_high numeric DEFAULT '-6.5'::numeric NOT NULL,
    weight_flush numeric DEFAULT 0.25 NOT NULL,
    weight_trend numeric DEFAULT 0.25 NOT NULL,
    weight_sentiment numeric DEFAULT 0.20 NOT NULL,
    weight_onchain numeric DEFAULT 0.15 NOT NULL,
    weight_risk numeric DEFAULT 0.15 NOT NULL,
    volatility_sensitivity numeric DEFAULT 0.25 NOT NULL,
    momentum_sensitivity numeric DEFAULT 0.6 NOT NULL,
    iteration integer DEFAULT 0 NOT NULL,
    last_reward numeric,
    last_change_log jsonb DEFAULT '[]'::jsonb NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    max_step_pct numeric DEFAULT 10 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    user_id uuid,
    CONSTRAINT engine_params_singleton CHECK ((id = 1))
);

CREATE TABLE public.learning_outcomes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    week_number integer NOT NULL,
    evaluated_at timestamp with time zone DEFAULT now() NOT NULL,
    params_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    per_coin_results jsonb DEFAULT '{}'::jsonb NOT NULL,
    avg_price_delta_7d numeric,
    avg_fill_rate numeric,
    reward_score numeric,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    user_id uuid NOT NULL
);

CREATE TABLE public.limit_orders (
