    leg text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.token_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    coingecko_id text NOT NULL,
    symbol text NOT NULL,
    side public.tx_side NOT NULL,
    quantity numeric NOT NULL,
    price_usd numeric NOT NULL,
    executed_at timestamp with time zone DEFAULT now() NOT NULL,
    note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT token_transactions_price_usd_check CHECK ((price_usd >= (0)::numeric)),
    CONSTRAINT token_transactions_quantity_check CHECK ((quantity > (0)::numeric))
);

CREATE TABLE public.tracked_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
