    weekly_capital numeric,
    invested_amount numeric,
    cash_reserve numeric,
    btc_market_pct numeric,
    btc_limit_pct numeric,
    btc_limit_distance numeric,
    btc_volatility_30d numeric,
    btc_momentum_30d numeric,
    eth_market_pct numeric,
    eth_limit_pct numeric,
    eth_limit_distance numeric,
    eth_volatility_30d numeric,
    eth_momentum_30d numeric,
    sol_market_pct numeric,
    sol_limit_pct numeric,
    sol_limit_distance numeric,
    sol_volatility_30d numeric,
    sol_momentum_30d numeric,
    user_id uuid NOT NULL
);

